def ids():
    return [a for _, _, items in GROUPS for a in items]


def render():
    n = len(ids())
    slots = json.load(open(MANIFEST))['slots']
    delivered = sum(slots.get(a[0], {}).get('status') == 'delivered' for a in ids())
    out = [START, '', '## Production art for the film edition', '',
           f'Requested 11 October 2026: {n} game assets for following the film (see '
           '[the adaptation plan](film-adaptation.md)). Each prompt is complete; paste it as it stands and '
           'attach the references it names (the character sheets and scene concepts are in '
           '[references/film-planning/](references/film-planning/index.html)). Sizes are 2× game units, as for '
           'the existing art, and match the sprite each one replaces so it drops into place. Name each file by its '
           'id and drop it in [`../intake/`](../intake/README.md). The ids are listed as `requested` in '
           '`assets/manifest.json`; until each arrives the game draws an interim cut-out or stand-in.', '',
           f'Delivery: {delivered} of {n} assets generated and prepared. '
           '[Delivery notes](generated/film-production/README.md) retain native originals and generation records.', '']
    for i, (title, blurb, items) in enumerate(GROUPS, 1):
        out += [f'### F{i}. {title}', '', blurb, '', '| Id | Size | Anchor | Replaces | Delivery |', '| --- | --- | --- | --- | --- |']
        out += [f'| `{a[0]}` | {a[2]} × {a[3]} | {a[4]} | {("`" + a[7] + "`") if a[7] else "new"} | ' +
                (f'[delivered](../assets/{a[0]}.webp)' if slots.get(a[0], {}).get('status') == 'delivered' else 'requested') + ' |' for a in items]
        out.append('')
        for aid, name, w, h, anchor, style, desc, _ in items:
            out += [f'#### `{aid}` — {name}', '', f'{w} × {h} px, anchor {anchor}.', '', f'> {desc} {style}', '']
    out.append(END)
    return '\n'.join(out)


def main():
    check = '--check' in sys.argv
    doc = open(DOC).read()
    block = render()
    if START in doc:
        new = doc[:doc.index(START)] + block + doc[doc.index(END) + len(END):]
    else:
        assert ANCHOR in doc, f'{ANCHOR!r} not found in image-requests.md'
        i = doc.index(ANCHOR)
        new = doc[:i] + block + '\n\n' + doc[i:]
    m = json.load(open(MANIFEST))
    slots = m['slots']
    changed = False
    wanted = {a[0]: a for a in ids()}
    for aid, a in wanted.items():
        s = slots.get(aid)
        if s is None:
            slots[aid] = s = {'status': 'requested', 'file': aid + '.webp'}
            changed = True
        if s.get('status') != 'delivered':
            # the shared sailor's frames load in every edition
            want = {'size': [a[2], a[3]], 'anchor': a[4], 'edition': 'shared' if aid.startswith('sailor-') else 'film'}
            if any(s.get(k) != v for k, v in want.items()):
                s.update(want)
                changed = True
    for aid in [k for k, v in slots.items() if v.get('edition') == 'film' and v.get('status') != 'delivered' and k not in wanted]:
        del slots[aid]
        changed = True
    if check:
        if new != doc or changed:
            raise SystemExit('image-requests.md or manifest.json is out of date: rerun build_film_assets.py')
        print('Film asset requests up to date')
        return
    open(DOC, 'w').write(new)
    if changed:
        with open(MANIFEST, 'w') as f:
            json.dump(m, f, indent=2)
            f.write('\n')
    print('wrote film asset requests:', len(wanted), 'assets')


if __name__ == '__main__':
    main()
